parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Prior authorization agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize PA request'); // one(): defined by guardPreamble; survives a lost item link
const ctx = $json; // fresh read of the PA request context
const docs = new Set((ctx.available_document_ids ?? []).map(String));
const criteriaIds = (ctx.criteria ?? []).map((c) => String(c.id));
const crit = out?.criteria ?? [];
const sameSet = (a, b) => JSON.stringify([...new Set(a)].sort()) === JSON.stringify([...new Set(b)].sort());
const docId = (ref) => String(ref).replace(/^DocumentReference\//, '');
const noop = ctx.pa_required === false;

if (!['draft', 'pending_submission'].includes(ctx.status)) reasons.push('PA request status is now ' + ctx.status);
if (ctx.coverage_active !== true) reasons.push('coverage is not active for the service date');
if (ctx.pa_required !== true && ctx.pa_required !== false) reasons.push('payer requirement for PA could not be established');
const dup = (ctx.open_authorizations ?? []).filter((a) => req.cpt_codes.includes(String(a.code)));
if (dup.length) reasons.push('an authorization is already open for the ordered service: ' + dup.map((a) => a.auth_id).join(', '));
if (out && !noop) {
  if (!sameSet(out.procedure_codes ?? [], req.cpt_codes)) reasons.push('requested procedure codes differ from the ordered codes');
  for (const d of out.diagnosis_codes ?? []) if (!/^[A-TV-Z][0-9][0-9A-Z](\.[0-9A-Z]{1,4})?$/.test(d)) reasons.push('a diagnosis code is not a well-formed ICD-10-CM code');
  if (!(out.diagnosis_codes ?? []).length) reasons.push('no diagnosis code supports the request');
  const answered = crit.map((c) => String(c.criterion_id));
  const unanswered = criteriaIds.filter((id) => !answered.includes(id));
  if (unanswered.length) reasons.push('payer criteria not addressed: ' + unanswered.join(', '));
  const open = crit.filter((c) => c.status !== 'documented');
  if (open.length) reasons.push(open.length + ' payer criteria not documented in the chart: ' + open.map((c) => c.criterion_id).join(', '));
  crit.filter((c) => c.status === 'documented').forEach((c) => {
    if (!(c.evidence ?? []).length) reasons.push('criterion ' + c.criterion_id + ' marked documented without evidence');
  });
  const cited = crit.flatMap((c) => c.evidence ?? []).filter((r) => String(r).startsWith('DocumentReference/')).map(docId);
  const unknown = [...cited, ...(out.attachments ?? []).map(docId)].filter((id) => !docs.has(id));
  if (unknown.length) reasons.push('documents not in the chart for this request: ' + [...new Set(unknown)].join(', '));
  if (!(out.attachments ?? []).length) reasons.push('no attachments selected');
  const n = (out.narrative ?? '').length;
  if (n < cfg.min_narrative_chars || n > cfg.max_narrative_chars) reasons.push('narrative is ' + n + ' characters, expected ' + cfg.min_narrative_chars + ' to ' + cfg.max_narrative_chars);
  if (out.urgency !== req.urgency) reasons.push('urgency changed from ' + req.urgency + ' to ' + out.urgency + '; the ordering clinician decides urgency');
}

const action = {
  type: 'submit_pa',
  pa_request_id: req.pa_request_id,
  payer_id: ctx.payer_id ?? null,
  transport: cfg.submission_transport,
  urgency: req.urgency,
  procedure_codes: req.cpt_codes,
  diagnosis_codes: out?.diagnosis_codes ?? [],
  attachments: (out?.attachments ?? []).map(docId),
  criteria: crit,
  narrative: out?.narrative ?? '',
};
// Ids and counts only in Slack. The clinician reads the narrative and evidence in the PA worklist.
const summary = noop
  ? 'PA request ' + req.pa_request_id + ': payer ' + ctx.payer_id + ' does not require prior authorization for the ordered codes.'
  : 'PA request ' + req.pa_request_id + ' · payer ' + ctx.payer_id + ' · ' + req.urgency + ' · via ' + cfg.submission_transport + '\n'
    + 'Drafted: narrative, ' + crit.filter((c) => c.status === 'documented').length + ' of ' + criteriaIds.length + ' payer criteria documented with evidence, ' + action.attachments.length + ' attachments. Review the narrative in the PA worklist before approving.';
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const sub = $json.submission ?? {};
const ok = ['submitted', 'pended', 'certified', 'denied'].includes($json.status) && !!sub.tracking_id
  && sub.transport === planned.transport && (sub.attachment_ids ?? []).length === planned.attachments.length;
const detail = 'PA request shows status ' + $json.status + ', tracking id ' + (sub.tracking_id ?? 'none') + ', transport ' + sub.transport + ', ' + (sub.attachment_ids ?? []).length + ' of ' + planned.attachments.length + ' attachments';
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize PA request'); } catch (e) {}
try { agent = one('Prior authorization agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'PA request ' + intake.pa_request_id + ' · ' + intake.urgency + ' · could not be prepared for submission';
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "utilization management",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

